node --input-type=module <<'JS'
import{chromium,expect} from '@playwright/test';
const b=await chromium.launch();
try{
const p=await b.newPage({viewport:{width:1280,height:900}});
await p.goto(process.env.TARGET_URL+'?sign-in');
await p.getByLabel('Access token').fill('{{token}}');
await p.getByRole('button',{name:'Open control plane'}).click();
const r=await p.request.get(new URL('/api/status',process.env.TARGET_URL).href,{headers:{Authorization:'Bearer {{token}}'}});
expect(r.ok()).toBe(true);
const s=await r.json();expect(s.repository).toBeTruthy();
const h=p.locator('.top-bar');
async function check(){
await expect(h.locator('.project-name')).toHaveText(s.repository);
await expect(h.locator('[data-release-line]')).toBeVisible();
await expect(p.locator('.brand')).toBeVisible();
expect(await h.evaluate(e=>e.scrollWidth<=e.clientWidth)).toBe(true);
}
async function go(name){
const m=p.getByRole('button',{name:'Menu',exact:true});
if(1280<651) await m.click();
await p.getByRole('navigation',{name:'Primary',exact:true}).getByRole('button',{name,exact:true}).click();
await check();
}
await go('Workers');await go('Work');
await p.locator('details.group-backlog>summary').click();
await p.locator('[data-row="{{itemKey}}"] .card-open').click();
await expect(p.locator('article.item-page')).toBeVisible();await check();
await p.getByRole('button',{name:'← Back',exact:true}).click();
await expect(p.locator('article.item-page')).toHaveCount(0);await check();
}finally{await b.close()}
